# Screener ensemble: CLV, peer lead-lag, 5d reversal, 20d risk-adjusted momentum,
# and range shock exhaustion.  Scores are cross-sectional ranks.
FACTOR_WEIGHTS = {"clv": .294, "peer": .226, "reversal": .174, "momentum": .171, "shock": .135}
MIN_W, MAX_W, REBALANCE_DAYS = .015, .16, 10
last_date = None

def ranks(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / len(good)
    return out

def bounded_weights(raw):
    # Iterative box/simplex projection: complete, long-only, fractional targets.
    w = {s: max(0., float(raw.get(s, 0.))) for s in UNIVERSE}
    z = sum(w.values()) or 1.; w = {s: x/z for s,x in w.items()}
    fixed = set()
    for _ in range(40):
        low = [s for s in UNIVERSE if s not in fixed and w[s] < MIN_W]
        high = [s for s in UNIVERSE if s not in fixed and w[s] > MAX_W]
        if not low and not high: break
        for s in low: w[s], fixed = MIN_W, fixed | {s}
        for s in high: w[s], fixed = MAX_W, fixed | {s}
        free = [s for s in UNIVERSE if s not in fixed]
        if not free: break
        rem = 1. - sum(w[s] for s in fixed)
        z = sum(max(w[s], 1e-12) for s in free)
        for s in free: w[s] = rem * w[s] / z
    z = sum(w.values())
    return {s: w[s]/z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict()
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 25: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, float); h = np.asarray(df.high, float); l = np.asarray(df.low, float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.
        market[s] = (c,h,l,r,str(df.iloc[-1].date))
    if len(market) < 12: return
    decision = max(v[4] for v in market.values())
    if last_date is not None:
        try:
            if (np.datetime64(decision,'D')-np.datetime64(last_date,'D'))/np.timedelta64(1,'D') < REBALANCE_DAYS: return
        except Exception: return
    clv, peer, reversal, momentum, shock, invvol, five = {}, {}, {}, {}, {}, {}, {}
    for s,(c,h,l,r,_) in market.items():
        if len(c) < 22: continue
        rng = np.maximum(h-l, 1e-12)
        clv[s] = float(np.mean(((2*c-h-l)/rng)[-3:]))
        reversal[s] = float(-np.mean(r[-5:]))
        vol = max(float(np.std(r[-20:])), .008); invvol[s] = 1./vol
        momentum[s] = float((c[-1]/max(c[-21],1e-12)-1.)/(vol+.01))
        five[s] = float(c[-1]/max(c[-6],1e-12)-1.)
        # Large one-day range with close away from the extreme indicates
        # exhaustion; prefer the subsequent rebound direction (contrarian).
        shock[s] = float(-r[-1] * min(abs(r[-1])/(np.std(r[-20:])+.002), 3.))
    med = float(np.median(list(five.values())))
    peer = {s:v-med for s,v in five.items()}
    rr = {k:ranks(v) for k,v in (("clv",clv),("peer",peer),("reversal",reversal),("momentum",momentum),("shock",shock))}
    score = {s: sum(FACTOR_WEIGHTS[k]*rr[k][s] for k in rr) for s in UNIVERSE}
    # Sideways/high-risk posture: keep full investment but use defensive
    # tradable assets and avoid an oversized crypto shock concentration.
    bearish = False
    if "SPX" in market:
        c = market["SPX"][0]; bearish = c[-1] < c[-21] and c[-1] < c[-6]
    if bearish:
        for s in ("XAU","US10Y","CN10Y"): score[s] += .18
        for s in ("BTC","ETH","WTI"): score[s] = max(.05, score[s]-.10)
    mean_iv = np.mean(list(invvol.values())) if invvol else 1.
    raw = {s:max(.01,score[s])*(.78+.22*invvol.get(s,mean_iv)/mean_iv) for s in UNIVERSE}
    rebalance_to_weights(bounded_weights(raw))
    last_date = decision

