    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / n
    return out

def simplex_box(raw):
    # Iterative capped simplex; preserves all 15 assets and exactly unit gross weight.
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    for _ in range(100):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        for s in UNIVERSE: w[s] = min(MAX_W, max(MIN_W, w[s]))
        fixed_sum = sum(w[s] for s in UNIVERSE if s not in free)
        if not free: break
        rem = 1.0 - fixed_sum
        z = sum(max(w[s], 1e-9) for s in free)
        for s in free: w[s] = rem * w[s] / z
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

